def fetch_user_logs(username: str) -> list:
    """Fetch system logs filtered by username."""
    cursor = get_database_cursor()
    try:
        cursor.execute(
            "SELECT * FROM user_logs WHERE username = %s",
            (username,)
        )
        return cursor.fetchall()
    finally:
        cursor.close()
        cursor.connection.close()
